function times(date){
 const jd=Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())/864e5+2440587.5,d=jd-2451545;
 const g=357.529+.98560028*d,q=280.459+.98564736*d,L=q+1.915*sin(g)+.02*sin(2*g),e=23.439-3.6e-7*d;
 let ra=Math.atan2(cos(e)*sin(L),cos(L))/R/15;ra=((ra%24)+24)%24;
 const D=Math.asin(sin(e)*sin(L))/R,eq=q/15-ra,EQ=((eq+12)%24+24)%24-12;
 const noon=12-S.lng/15-EQ,la=S.lat;
 const h=alt=>{const c=(sin(alt)-sin(D)*sin(la))/(cos(D)*cos(la));return Math.acos(Math.max(-1,Math.min(1,c)))/R/15};
 const asrAlt=Math.atan(1/(S.asr+tan(Math.abs(la-D))))/R;
 const M=cmGet(),mg=noon+h(-.833),u=[noon-h(-M[2]),noon-h(-.833),noon,noon+h(asrAlt),mg,M[4]?mg+M[4]/60:noon+h(-M[3])];
 const base=Date.UTC(date.getFullYear(),date.getMonth(),date.getDate());
 return u.map(x=>new Date(base+(x*60+S.adj)*6e4));
}
