const _hf=new Intl.DateTimeFormat("en-u-ca-islamic-umalqura",{year:"numeric",month:"numeric",day:"numeric",timeZone:"UTC"});
function hp(ms){const p=_hf.formatToParts(ms),g=t=>+p.find(x=>x.type==t).value;return[g("year"),g("month"),g("day")]}
const hcmp=(a,y,m,d)=>a[0]!=y?a[0]-y:a[1]!=m?a[1]-m:a[2]-d;
const HU={};
function hUQ(Y){if(HU[Y])return HU[Y];let ms=Date.UTC(622,6,16,12)+Math.round((Y-1)*354.3671*DAY);
 for(let i=0;i<8;i++){const a=hp(ms),df=(a[0]-Y)*354.37+(a[1]-1)*29.53+(a[2]-1);if(Math.abs(df)<1)break;ms-=Math.round(df)*DAY}
 for(let i=0;i<60;i++){const c=hcmp(hp(ms),Y,1,1);if(c==0)break;ms+=(c<0?1:-1)*DAY}
 {const D0=new Date(ms);ms=Date.UTC(D0.getUTCFullYear(),D0.getUTCMonth(),D0.getUTCDate(),12)}
 const r=[];for(let d=0;d<390&&r.length<13;d++){const t=ms+d*DAY,a=hp(t);if(a[2]==1&&((a[0]==Y&&a[1]==r.length+1)||(a[0]==Y+1&&a[1]==1&&r.length==12)))r.push(t)}
 return HU[Y]=r}
const hUL=(y,m)=>Math.round((hUQ(y)[m]-hUQ(y)[m-1])/DAY);
function mstart(Y,m){if(m>12){Y++;m=1}let t=hUQ(Y)[m-1];const o=Y*12+m-1,L=S.hlen||{};
 for(const k in L){const[y,mm]=k.split("-").map(Number);if(y*12+mm-1<o)t+=(L[k]-hUL(y,mm))*DAY}return t}
const mlen=(Y,m)=>Math.round((mstart(Y,m+1)-mstart(Y,m))/DAY);
function todayH(){const n=new Date(),t=Date.UTC(n.getFullYear(),n.getMonth(),n.getDate(),12),y0=hp(t)[0];
 let r=[y0,1,1];for(let y=y0-1;y<=y0+1;y++)for(let m=1;m<=12;m++){const s=mstart(y,m);if(s<=t)r=[y,m,Math.round((t-s)/DAY)+1]}return r}
function hijri(){try{const[y,m,d]=todayH();return new Intl.DateTimeFormat("ar",{weekday:"long"}).format(new Date())+" "+d.toLocaleString("ar")+" "+MN[m-1]+" "+y.toLocaleString("ar",{useGrouping:false})+" هـ"}catch(e){return new Intl.DateTimeFormat("ar-SA-u-ca-islamic-umalqura",{dateStyle:"full"}).format(new Date())}}
