function qasPt(){
 const {s,a}=qas,p=qPageOf(s,a),T=qas.t||0,len=QD.text[s-1].length;
 const top=`<div class="qlab">أين تتوقف التلاوة؟</div><div class="qopts"><div class="qopt" onclick="qasTo('p',${p})"><i>${IC.playto}</i><b>نهاية الصفحة</b><span>ص ${AD(p)}</span></div><div class="qopt" onclick="qasTo('s',${s})"><i>${IC.book}</i><b>نهاية السورة</b><span>${QD.names[s-1]}</span></div><div class="qopt" onclick="qasTo('q')"><i class="big2">∞</i><b>تلاوة مستمرة</b><span>حتى الختمة</span></div></div>`;
 const rp=`<div class="qar2" onclick="qrepT()"><b>🔁 التشغيل المتكرر</b><span class="mu">${S.qrep?"مفعّل ✓":"معطّل"}</span></div>`;
 const tb=`<div class="qtabs">${["الآيات","الصفحات","السور"].map((t,i)=>`<button class="${T==i?"on":""}" onclick="qas.t=${i};qasR()">${t}</button>`).join("")}</div>`;
 let rows="";
 if(T==0){for(let i=a;i<=len;i++)rows+=`<div class="qli" onclick="qasTo('a',${i})"><span class="qnum">${AD(i)}</span><div class="qlt"><b>${QD.names[s-1]} · آية ${AD(i)}</b><div class="qt qln">${QD.text[s-1][i-1]}</div></div></div>`}
 else if(T==1){for(let i=p;i<=604;i++)rows+=`<div class="qli" onclick="qasTo('p',${i})"><span class="qnum">${AD(i)}</span><div class="qlt"><b>الصفحة ${AD(i)}</b><div class="mu">${qSur(i).map(x=>QD.names[x-1]).join(" · ")}</div></div></div>`}
 else{for(let i=s;i<=114;i++)rows+=`<div class="qli" onclick="qasTo('s',${i})"><span class="qnum">${AD(i)}</span><div class="qlt"><b>${QD.names[i-1]}</b><div class="mu">${AD(QD.text[i-1].length)} آية</div></div></div>`}
 return top+rp+tb+`<div class="qlist">${rows}</div>`}
function qrepT(){S.qrep=S.qrep?0:1;save();qtoast(S.qrep?"التشغيل المتكرر مفعّل: تعيد التلاوة نفسها عند انتهائها":"التشغيل المتكرر معطّل");qasR()}
function qasNote(){
 const v=esc((S.qnotes||{})[qas.s+":"+qas.a]||"");
 return `<div class="qac" style="padding:12px"><textarea id="qnt" oninput="qntS(this.value)" placeholder="اكتب ملاحظتك على هذه الآية…" style="width:100%;min-height:220px;font:inherit;background:transparent;color:var(--tx);border:0;outline:0;resize:vertical;user-select:text;-webkit-user-select:text">${v}</textarea></div>`}
