async function wakeOn(){if(S.wake===false||!$("#qv")||WL)return;try{if(navigator.wakeLock){WL=await navigator.wakeLock.request("screen");WL.addEventListener("release",()=>{WL=null})}}catch(e){WL=null}}
function wakeOff(){try{WL&&WL.release()}catch(e){}WL=null}
document.addEventListener("visibilitychange",()=>{if(document.visibilityState=="visible"){if($("#qv"))wakeOn();snReset();ntTick()}});
