  if(m2==12&&d2==1)P("dhh","🌙 غدًا أول أيام ذي الحجة","إن نويتَ الأضحية فأمسك عن شعرك وأظفارك من الآن إلى أن تذبح.",SN_DH1,SN_ADH,0);
