   TFR=m.tafsirs.map(x=>({id:x.id,n:x.n,au:x.au||"",lg:x.lg||"arabic",sl:x.sl||""}));try{await idbSet("tfres",TFR)}catch(e){}
   S.tfd=S.tfd||{};TFD.forEach(d=>{const r=TFR.find(x=>d.re.test(x.n+" "+x.sl)&&(d.k!="mkh"||/arab/i.test(x.lg)));if(r)S.tfd[d.k]=r.id});const dv=Object.values(S.tfd);S.qtf=(S.qtf||[]).filter(i=>!dv.includes(i));
   S.tfdn=S.tfdn||{};
